test("frame opaque 40add0 pure gates JS oracle matches PE control flow", () => {
  /* Empty list + non-null field_4 → pure false (no host). */
  assert.equal(frameOpaque40add0NeedsHost(1, 0), false);
  assert.equal(frameOpaque40add0NeedsHost(0xdeadbeef, 0), false);
  /* field_4==0 → assert host 0xa112c0. */
  assert.equal(frameOpaque40add0NeedsHost(0, 0), true);
  assert.equal(frameOpaque40add0NeedsHost(0, 5), true);
  /* Non-empty list → string-walk host. */
  assert.equal(frameOpaque40add0NeedsHost(1, 1), true);
  assert.equal(frameOpaque40add0NeedsHost(1, 0xffffffff), true);

  /* Match-path bit test: (bitfield & (1<<(i&31))) != 0; i<0 → false. */
  assert.equal(frameOpaque40add0BitResult(0, 0), false);
  assert.equal(frameOpaque40add0BitResult(1, 0), true);
  assert.equal(frameOpaque40add0BitResult(0x00000004, 2), true);
  assert.equal(frameOpaque40add0BitResult(0x00000004, 1), false);
  assert.equal(frameOpaque40add0BitResult(0x80000000, 31), true);
  assert.equal(frameOpaque40add0BitResult(0x00000001, 32), true); /* i&31 → 0 */
  assert.equal(frameOpaque40add0BitResult(0xffffffff, -1), false);
  assert.equal(frameOpaque40add0BitResult(0xffffffff, -100), false);

  /* Post-false-probe pure terminal (0x4213de). */
  assert.deepEqual(
    frameOpaque4212c0Secondary3AfterProbeFalse({
      mode: 4, secondary: 3, field3c: 7, flag4c: 1,
    }),
    { mode: 4, secondary: 3 },
    "both flags set: pure early return no clear",
  );
  assert.deepEqual(
    frameOpaque4212c0Secondary3AfterProbeFalse({
      mode: 4, secondary: 3, field3c: 7, flag4c: 0,
    }),
    { mode: 0, secondary: 0 },
    "flag4c clear: clear both",
  );
  assert.deepEqual(
    frameOpaque4212c0Secondary3AfterProbeFalse({
      mode: 2, secondary: 3, field3c: 0, flag4c: 1,
    }),
    { mode: 0, secondary: 0 },
    "field3c zero: clear both",
  );
  assert.deepEqual(
    frameOpaque4212c0Secondary3AfterProbeFalse({
      mode: 9, secondary: 3, field3c: 0, flag4c: 0,
    }),
    { mode: 0, secondary: 0 },
    "both zero: clear both",
  );
});

test("frame opaque 40add0 list-walk pure stride/index/SSO JS oracle matches PE CF", () => {
  assert.equal(FRAME_OPAQUE_40ADD0_ENTRY_STRIDE, 0x18);
  assert.equal(FRAME_OPAQUE_40ADD0_SSO_CAPACITY, 0x10);
  assert.equal(frameOpaque40add0EntryStride(), 0x18);

  /* SSO: capacity < 0x10 → inline at entry. */
  assert.equal(frameOpaque40add0SsoInline(0), true);
  assert.equal(frameOpaque40add0SsoInline(0xf), true);
  assert.equal(frameOpaque40add0SsoInline(0x10), false);
  assert.equal(frameOpaque40add0SsoInline(0x20), false);
  assert.equal(frameOpaque40add0SsoInline(0xffffffff), false);

  assert.equal(frameOpaque40add0EntryDataAddr(0x1000, 0xf, 0xdead), 0x1000);
  assert.equal(frameOpaque40add0EntryDataAddr(0x1000, 0x10, 0xdead), 0xdead);
  assert.equal(frameOpaque40add0EntryDataAddr(0x1000, 0x20, 0xabcd), 0xabcd);

  /* Unsigned in-range (cmp edi, ebx / jb). */
  assert.equal(frameOpaque40add0WalkInRange(0, 1), true);
  assert.equal(frameOpaque40add0WalkInRange(0, 0), false);
  assert.equal(frameOpaque40add0WalkInRange(3, 3), false);
  assert.equal(frameOpaque40add0WalkInRange(2, 3), true);
  assert.equal(frameOpaque40add0WalkInRange(0xffffffff, 1), false);

  /* After miss: index++, entry += 0x18, continue if index < count. */
  {
    const s = { index: 0, entryAddr: 0x2000 };
    const r = frameOpaque40add0WalkAfterMiss(s, 3);
    assert.equal(r.continue, true);
    assert.equal(r.index, 1);
    assert.equal(r.entryAddr, 0x2018);
    assert.equal(s.index, 1);
    assert.equal(s.entryAddr, 0x2018);
  }
  {
    const s = { index: 2, entryAddr: 0x2030 };
    const r = frameOpaque40add0WalkAfterMiss(s, 3);
    assert.equal(r.continue, false);
    assert.equal(r.index, 3);
    assert.equal(r.entryAddr, 0x2048);
  }
  {
    /* Single-entry list: first miss exhausts. */
    const s = { index: 0, entryAddr: 0x3000 };
    const r = frameOpaque40add0WalkAfterMiss(s, 1);
    assert.equal(r.continue, false);
    assert.equal(r.index, 1);
    assert.equal(r.entryAddr, 0x3018);
  }
  {
    /* Walk full count of 4 with no match → four advances, last continue false. */
    const s = { index: 0, entryAddr: 0 };
    let steps = 0;
    let cont = true;
    while (cont) {
      const r = frameOpaque40add0WalkAfterMiss(s, 4);
      cont = r.continue;
      steps++;
      assert.ok(steps <= 4);
    }
    assert.equal(steps, 4);
    assert.equal(s.index, 4);
    assert.equal(s.entryAddr, 0x18 * 4);
  }

  /* First-match index from equality flags. */
  assert.equal(frameOpaque40add0FirstMatchIndex(null, 3), -1);
  assert.equal(frameOpaque40add0FirstMatchIndex([], 0), -1);
  assert.equal(frameOpaque40add0FirstMatchIndex([0, 0, 0], 3), -1);
  assert.equal(frameOpaque40add0FirstMatchIndex([1, 0, 0], 3), 0);
  assert.equal(frameOpaque40add0FirstMatchIndex([0, 0, 1], 3), 2);
  assert.equal(frameOpaque40add0FirstMatchIndex([0, 5, 1], 3), 1);
  assert.equal(frameOpaque40add0FirstMatchIndex([0, 0, 1, 1], 2), -1); /* count caps walk */
  /* Match at index 2 + bit_result pure probe composition. */
  const mi = frameOpaque40add0FirstMatchIndex([0, 0, 1], 3);
  assert.equal(mi, 2);
  assert.equal(frameOpaque40add0BitResult(0x00000004, mi), true);
  assert.equal(frameOpaque40add0BitResult(0x00000000, mi), false);
});

test("frame opaque 40add0 inlined strcmp + equality-pack pure JS oracle matches PE CF", () => {
  /* Inlined strcmp at 0x0040ae12: equal → 0; unequal → ±1 (sbb/or). */
  assert.equal(frameOpaque40add0Strcmp("End", "End"), 0);
  assert.equal(frameOpaque40add0Strcmp("", ""), 0);
  assert.equal(frameOpaque40add0Strcmp("A", "A"), 0);
  assert.equal(frameOpaque40add0Strcmp("AB", "AB"), 0);
  assert.equal(frameOpaque40add0Strcmp("ABC", "ABC"), 0); /* odd length via pair */
  /* Third byte: 'd'(0x64) < 'e'(0x65) → sbb CF → -1 */
  assert.equal(frameOpaque40add0Strcmp("End", "Ene"), -1);
  assert.equal(frameOpaque40add0Strcmp("Ene", "End"), 1);
  assert.equal(frameOpaque40add0Strcmp("End", "En"), 1); /* longer > shorter at NUL */
  assert.equal(frameOpaque40add0Strcmp("En", "End"), -1);
  assert.equal(frameOpaque40add0Strcmp("X", "Y"), -1);
  assert.equal(frameOpaque40add0Strcmp("Y", "X"), 1);
  /* First-byte mismatch. */
  assert.equal(frameOpaque40add0Strcmp("a", "b"), -1);
  assert.equal(frameOpaque40add0Strcmp("b", "a"), 1);
  /* Second-byte mismatch inside a pair. */
  assert.equal(frameOpaque40add0Strcmp("Aa", "Ab"), -1);
  assert.equal(frameOpaque40add0Strcmp("Ab", "Aa"), 1);
  /* Null treated as unequal (+1). */
  assert.equal(frameOpaque40add0Strcmp(null, "End"), 1);
  assert.equal(frameOpaque40add0Strcmp("End", null), 1);
  /* Byte arrays (0-terminated). */
  assert.equal(frameOpaque40add0Strcmp([0x45, 0x6e, 0x64, 0], [0x45, 0x6e, 0x64, 0]), 0);
  assert.equal(frameOpaque40add0Strcmp([1, 2, 0], [1, 3, 0]), -1);

  assert.equal(frameOpaque40add0StrcmpEqual("End", "End"), true);
  assert.equal(frameOpaque40add0StrcmpEqual("End", "end"), false);
  assert.equal(frameOpaque40add0StrcmpEqual("", ""), true);
  assert.equal(frameOpaque40add0StrcmpEqual(null, ""), false);

  /* Equality-pack pure probe: flags + bitfield → al. */
  assert.equal(frameOpaque40add0ProbeFromEqualFlags(null, 3, 0xffffffff), false);
  assert.equal(frameOpaque40add0ProbeFromEqualFlags([0, 0, 0], 3, 0xffffffff), false);
  assert.equal(frameOpaque40add0ProbeFromEqualFlags([1, 0, 0], 3, 0x1), true);
  assert.equal(frameOpaque40add0ProbeFromEqualFlags([1, 0, 0], 3, 0x0), false);
  assert.equal(frameOpaque40add0ProbeFromEqualFlags([0, 0, 1], 3, 0x4), true);
  assert.equal(frameOpaque40add0ProbeFromEqualFlags([0, 0, 1], 3, 0x2), false);
  assert.equal(frameOpaque40add0ProbeFromEqualFlags([0, 1], 2, 0x2), true);
  /* 4212c0 needle "End" scenario: match at index 0, bit 0 set → true. */
  assert.equal(frameOpaque40add0ProbeFromEqualFlags([1], 1, 0x1), true);
  /* Match index 31 bit set. */
  assert.equal(
    frameOpaque40add0ProbeFromEqualFlags(Array(31).fill(0).concat([1]), 32, 0x80000000),
    true,
  );

  /* needs_host_with_flags: assert always host; flags ready → pure. */
  assert.equal(frameOpaque40add0NeedsHostWithFlags(0, 0, 0), true);
  assert.equal(frameOpaque40add0NeedsHostWithFlags(0, 5, 1), true); /* assert wins */
  assert.equal(frameOpaque40add0NeedsHostWithFlags(1, 0, 0), false); /* empty list */
  assert.equal(frameOpaque40add0NeedsHostWithFlags(1, 3, 0), true); /* live strcmp */
  assert.equal(frameOpaque40add0NeedsHostWithFlags(1, 3, 1), false); /* flags pack */
  assert.equal(frameOpaque40add0NeedsHostWithFlags(0xdeadbeef, 0, 1), false);
});

test("frame opaque 98dba0 pure mode/float JS oracle matches PE control flow", () => {
  assert.deepEqual(frameOpaque98dba0Bvar2CounterStep(9, 0), {
    hostFun00746560: false,
    counter: 9,
  });
  assert.deepEqual(frameOpaque98dba0Bvar2CounterStep(9, 1), {
    hostFun00746560: true,
    counter: 10,
  });
  assert.deepEqual(frameOpaque98dba0Bvar2CounterStep(10, 1), {
    hostFun00746560: false,
    counter: 11,
  });

  for (const c of modeFloatCases) {
    const got = frameOpaque98dba0ModeFloatStep(c.state, c.bVar2, c.manager);
    assert.equal(got.fallthrough, c.expect.fallthrough, `${c.name} fallthrough`);
    assert.equal(got.mode, c.expect.mode, `${c.name} mode`);
    assert.equal(got.flag, c.expect.flag, `${c.name} flag`);
    assert.equal(got.counter, c.expect.counter, `${c.name} counter`);
    approxEqual(got.float170, c.expect.float170, `${c.name} float170`);
    approxEqual(got.float2d0, c.expect.float2d0, `${c.name} float2d0`);
  }

  const clamped = frameOpaque98dba0ClampFloats(-0.5, 1.5);
  assert.equal(clamped.float170, 0.0);
  assert.equal(clamped.float2d0, f32(0x3f800000));
  const mid = frameOpaque98dba0ClampFloats(0.25, 0.75);
  assert.equal(mid.float170, 0.25);
  assert.equal(mid.float2d0, 0.75);
});

const timerStepCases = [
  {
    name: "timer<=0 pure no-op",
    state: { timer: 0, x: 1.0, y: 2.0 },
    genrand: 0x12345678,
    expectApplied: false,
  },
  {
    name: "timer negative pure no-op",
    state: { timer: -3, x: 0.5, y: 0.25 },
    genrand: 0xffffffff,
    expectApplied: false,
  },
  {
    name: "timer=1 countdown to 0 + half decay",
    state: { timer: 1, x: 2.0, y: 4.0 },
    genrand: 0,
    expectApplied: true,
  },
  {
    name: "timer=10 mid phase",
    state: { timer: 10, x: 0.0, y: 0.0 },
    genrand: 0x80000000,
    expectApplied: true,
  },
  {
    name: "timer=5 nonzero xy + high genrand",
    state: { timer: 5, x: 1.5, y: -0.5 },
    genrand: 0xdeadbeef,
    expectApplied: true,
  },
  {
    name: "timer=2 low genrand",
    state: { timer: 2, x: 0.1, y: 0.2 },
    genrand: 1,
    expectApplied: true,
  },
];

test("frame opaque 98dba0 timer pure JS oracle matches PE control flow", () => {
  assert.equal(frameOpaque98dba0TimerNeedsHost(0), false);
  assert.equal(frameOpaque98dba0TimerNeedsHost(1), true);
  assert.equal(frameOpaque98dba0TimerNeedsHost(-1), false);
  assert.equal(frameOpaque98dba0TimerNeedsHost(10), true);

  /* unit float: 0 → 0; 0x80000000 → 0.5 exactly (2^31 / 2^32).
     0xffffffff → f32 rounds 2^32-1 to 2^32 so unit can be exactly 1.0 (PE). */
  assert.equal(frameOpaque98dba0TimerUnitFloat(0), 0.0);
  approxEqual(frameOpaque98dba0TimerUnitFloat(0x80000000), 0.5, "unit mid");
  assert.ok(frameOpaque98dba0TimerUnitFloat(0xffffffff) <= 1.0);
  assert.ok(frameOpaque98dba0TimerUnitFloat(0xffffffff) >= 0.99);

  for (const c of timerStepCases) {
    const got = frameOpaque98dba0TimerStep(c.state, c.genrand);
    assert.equal(got.applied, c.expectApplied, `${c.name} applied`);
    if (!c.expectApplied) {
      assert.equal(got.timer, c.state.timer | 0, `${c.name} timer unchanged`);
      assert.equal(got.x, Math.fround(c.state.x), `${c.name} x unchanged`);
      assert.equal(got.y, Math.fround(c.state.y), `${c.name} y unchanged`);
      continue;
    }
    assert.equal(got.timer, (c.state.timer - 1) | 0, `${c.name} countdown`);
    /* Applied path must mutate floats under normal samples (t may be 0). */
    if (got.timer === 0) {
      /* t=0 → x' = x*0.5, y' = y*0.5 */
      approxEqual(got.x, Math.fround(Math.fround(c.state.x) * 0.5), `${c.name} x half`);
      approxEqual(got.y, Math.fround(Math.fround(c.state.y) * 0.5), `${c.name} y half`);
    }
  }

  /* Explicit timer=1 / genrand=0: angle=0, cos=1, sin=0, t=0 → half decay. */
  const z = frameOpaque98dba0TimerStep({ timer: 1, x: 8, y: 6 }, 0);
  assert.equal(z.applied, true);
  assert.equal(z.timer, 0);
  approxEqual(z.x, 4.0, "explicit x");
  approxEqual(z.y, 3.0, "explicit y");
});

test("frame opaque 98dba0 player-walk pure CF JS oracle (ABI v15)", () => {
  assert.equal(FRAME_OPAQUE_HOST_98DBA0_VA, 0x0098dba0);
  assert.equal(FRAME_OPAQUE_HOST_956110_VA, 0x00956110);
  assert.equal(FRAME_OPAQUE_HOST_90B100_VA, 0x0090b100);
  assert.equal(FRAME_OPAQUE_HOST_A20390_VA, 0x00a20390);
  assert.equal(FRAME_OPAQUE_HOST_746560_VA, 0x00746560);
  assert.equal(FRAME_OPAQUE_PLAYER_ID_OFF, 0x1618);

  /* vector_count: (end-begin)>>2 signed. */
  assert.equal(frameOpaque98dba0VectorCount(0x1000, 0x1000), 0);
  assert.equal(frameOpaque98dba0VectorCount(0x1000, 0x1004), 1);
  assert.equal(frameOpaque98dba0VectorCount(0x1000, 0x1010), 4);
  /* wrap: end < begin → negative delta sar 2 */
  assert.equal(frameOpaque98dba0VectorCount(0x10, 0x0), (-16) >> 2);

  assert.equal(frameOpaque98dba0EmptyFatalNeeded(0), true);
  assert.equal(frameOpaque98dba0EmptyFatalNeeded(1), false);
  assert.equal(frameOpaque98dba0WalkNeeded(0), false);
  assert.equal(frameOpaque98dba0WalkNeeded(2), true);

  assert.equal(frameOpaque98dba0IndexInRange(0, 1), true);
  assert.equal(frameOpaque98dba0IndexInRange(1, 1), false);
  assert.equal(frameOpaque98dba0IndexInRange(0xffffffff, 1), false);
  assert.equal(frameOpaque98dba0PlayerSlotAddr(0x2000, 3), 0x200c);

  assert.equal(frameOpaque98dba0MpRangeEmpty(0x1, 0x1), true);
  assert.equal(frameOpaque98dba0MpRangeEmpty(0x1, 0x5), false);
  assert.equal(frameOpaque98dba0MpIdEq(7, 7), true);
  assert.equal(frameOpaque98dba0MpIdEq(7, 8), false);

  assert.equal(frameOpaque98dba0MpFirstMatchIndex([1, 2, 3], 3, 2), 1);
  assert.equal(frameOpaque98dba0MpFirstMatchIndex([1, 2, 3], 3, 9), -1);
  assert.equal(frameOpaque98dba0MpFirstMatchIndex(null, 3, 1), -1);
  assert.equal(frameOpaque98dba0MpFirstMatchIndex([], 0, 1), -1);

  {
    const r = frameOpaque98dba0MpWalkAfterMiss(0, 3);
    assert.equal(r.cont, true);
    assert.equal(r.index, 1);
    const end = frameOpaque98dba0MpWalkAfterMiss(2, 3);
    assert.equal(end.cont, false);
    assert.equal(end.index, 3);
  }

  assert.equal(frameOpaque98dba0Bvar2Phase1Sticky(0), false);
  assert.equal(frameOpaque98dba0Bvar2Phase1Sticky(1), true);
  assert.equal(frameOpaque98dba0Bvar2Phase1Result(1, 0, 0), true);
  assert.equal(frameOpaque98dba0Bvar2Phase1Result(0, 1, 1), false);
  assert.equal(frameOpaque98dba0Bvar2Phase1Result(0, 0, 1), true);
  assert.equal(frameOpaque98dba0Bvar2Phase1Result(0, 0, 0), false);

  assert.equal(frameOpaque98dba0Phase2RttiNeeded(1, 0), false);
  assert.equal(frameOpaque98dba0Phase2RttiNeeded(0, 1), false);
  assert.equal(frameOpaque98dba0Phase2RttiNeeded(0, 0), true);

  assert.equal(frameOpaque98dba0Bvar2Phase3Result(1, 0, 0, 0), true);
  assert.equal(frameOpaque98dba0Bvar2Phase3Result(0, 1, 0, 1), true);
  assert.equal(frameOpaque98dba0Bvar2Phase3Result(0, 0, 1, 0), false);
  assert.equal(frameOpaque98dba0Bvar2Phase3Result(0, 0, 0, 1), false);

  /* Sticky in → stays true even if phase3 inactive. */
  assert.equal(
    frameOpaque98dba0Bvar2PlayerStep(1, 0, 0, 0, 0, 0, 0, 0),
    true,
  );
  /* Phase1 false; phase3 skip → false. */
  assert.equal(
    frameOpaque98dba0Bvar2PlayerStep(0, 0, 0, 1, 1, 0, 1, 1),
    false,
  );
  /* Phase1 true via 956110; phase3 inactive → true. */
  assert.equal(
    frameOpaque98dba0Bvar2PlayerStep(0, 0, 1, 0, 0, 0, 0, 0),
    true,
  );
  /* Phase1 false; phase3 active + local + 956110 → true. */
  assert.equal(
    frameOpaque98dba0Bvar2PlayerStep(0, 0, 0, 0, 1, 0, 1, 1),
    true,
  );

  {
    const step = frameOpaque98dba0WalkAfterPlayer(0, 2);
    assert.equal(step.cont, true);
    assert.equal(step.index, 1);
    const last = frameOpaque98dba0WalkAfterPlayer(1, 2);
    assert.equal(last.cont, false);
  }

  /* Two players: first sets bVar2 via 956110; second sticky keeps it. */
  const probes = [
    /* p0 */ 0, 1, 1, 0, 0, 0, 0, 0,
    /* p1 */ 0, 0, 0, 0, 0, 0, 0, 0,
  ];
  assert.equal(frameOpaque98dba0Bvar2ApplyFromProbes(probes, 2), true);
  assert.equal(frameOpaque98dba0Bvar2ApplyFromProbes(null, 2), false);
  assert.equal(frameOpaque98dba0Bvar2ApplyFromProbes([], 0), false);

  assert.deepEqual(frameOpaque98dba0WalkResidualPlan(0), {
    emptyFatal: true,
    walkNeeded: false,
    pureCfOk: false,
    hostBody: false,
    playerCount: 0,
  });
  assert.deepEqual(frameOpaque98dba0WalkResidualPlan(3), {
    emptyFatal: false,
    walkNeeded: true,
    pureCfOk: true,
    hostBody: true,
    playerCount: 3,
  });
});

test("frame opaque 956110 walk-probe pure CF JS oracle (ABI v16)", () => {
  assert.equal(FRAME_OPAQUE_HOST_956110_VA, 0x00956110);
  assert.equal(FRAME_OPAQUE_HOST_864C30_VA, 0x00864c30);
  assert.equal(FRAME_OPAQUE_HOST_A20940_VA, 0x00a20940);
  assert.equal(FRAME_OPAQUE_956110_PATH_ID_NEG1_WALK, 0);
  assert.equal(FRAME_OPAQUE_956110_PATH_GENERAL, 1);

  /* net_gate: Manager+8==2 && global!=0 */
  assert.equal(frameOpaque956110NetGate(2, 1), true);
  assert.equal(frameOpaque956110NetGate(2, 0), false);
  assert.equal(frameOpaque956110NetGate(1, 1), false);
  assert.equal(frameOpaque956110NetGate(0, 0xffffffff), false);
  assert.equal(frameOpaque956110NetGate(2, 0xffffffff), true);

  assert.equal(frameOpaque956110IdIsNeg1(-1), true);
  assert.equal(frameOpaque956110IdIsNeg1(0), false);
  assert.equal(frameOpaque956110IdIsNeg1(0xd), false);

  assert.equal(
    frameOpaque956110Path(1, -1),
    FRAME_OPAQUE_956110_PATH_GENERAL,
  );
  assert.equal(
    frameOpaque956110Path(0, 0),
    FRAME_OPAQUE_956110_PATH_GENERAL,
  );
  assert.equal(
    frameOpaque956110Path(0, -1),
    FRAME_OPAQUE_956110_PATH_ID_NEG1_WALK,
  );

  assert.equal(frameOpaque956110NetEarlyResult(0), false);
  assert.equal(frameOpaque956110NetEarlyResult(1), true);
  assert.equal(frameOpaque956110NetEarlyResult(0x100), false); /* low byte 0 */
  assert.equal(frameOpaque956110NetEarlyResult(0x101), true);

  assert.equal(frameOpaque956110ApplyFromVtableResults([0, 0, 1], 3), true);
  assert.equal(frameOpaque956110ApplyFromVtableResults([0, 0, 0], 3), false);
  assert.equal(frameOpaque956110ApplyFromVtableResults(null, 3), false);
  assert.equal(frameOpaque956110ApplyFromVtableResults([1], 0), false);

  /* Net early post wins when gate open + host ok. */
  assert.equal(
    frameOpaque956110ResultFromSamples({
      netGateOpen: true,
      netHostOk: true,
      netOutByte: 1,
      mpEmpty: 0,
      id: -1,
      vtableResults: [0],
      vtableCount: 1,
      generalResult: 0,
    }),
    true,
  );
  /* Net fail fallthrough → id==-1 walk. */
  assert.equal(
    frameOpaque956110ResultFromSamples({
      netGateOpen: true,
      netHostOk: false,
      netOutByte: 1,
      mpEmpty: 0,
      id: -1,
      vtableResults: [0, 1],
      vtableCount: 2,
      generalResult: 0,
    }),
    true,
  );
  /* General path pure post. */
  assert.equal(
    frameOpaque956110ResultFromSamples({
      netGateOpen: false,
      netHostOk: false,
      mpEmpty: 1,
      id: 0xd,
      generalResult: 1,
    }),
    true,
  );
  assert.equal(
    frameOpaque956110ResultFromSamples({
      netGateOpen: false,
      netHostOk: false,
      mpEmpty: 0,
      id: 7,
      generalResult: 0,
    }),
    false,
  );

  assert.deepEqual(frameOpaque956110ResidualPlan(2, 1, 0, -1), {
    netGate: true,
    path: FRAME_OPAQUE_956110_PATH_ID_NEG1_WALK,
    host864c30: true,
    hostVtableWalk: true,
    hostGeneral: false,
    pureCfOk: true,
    hostBody: true,
  });
  assert.deepEqual(frameOpaque956110ResidualPlan(0, 0, 1, 5), {
    netGate: false,
    path: FRAME_OPAQUE_956110_PATH_GENERAL,
    host864c30: false,
    hostVtableWalk: false,
    hostGeneral: true,
    pureCfOk: true,
    hostBody: true,
  });
});

test("frame opaque 864c30 net-early pure CF JS oracle (ABI v17)", () => {
  assert.equal(FRAME_OPAQUE_HOST_864C30_VA, 0x00864c30);
  assert.equal(FRAME_OPAQUE_HOST_874910_VA, 0x00874910);
  assert.equal(FRAME_OPAQUE_HOST_6A80F0_VA, 0x006a80f0);
  assert.equal(FRAME_OPAQUE_864C30_CAPABILITY_BIT, 0x2000);
  assert.equal(FRAME_OPAQUE_864C30_PACK_KIND_IMM, 0xd);
  assert.equal(FRAME_OPAQUE_864C30_NET_FIELD10_OFF, 0x10);
  assert.equal(FRAME_OPAQUE_864C30_LUA_REGISTRYINDEX, 0xfff0b9d8);
  assert.equal(frameOpaque864c30PackKindImm(), 0xd);

  /* capability: bit 0x2000 on flag dword */
  assert.equal(frameOpaque864c30CapabilityGate(0), false);
  assert.equal(frameOpaque864c30CapabilityGate(0x2000), true);
  assert.equal(frameOpaque864c30CapabilityGate(0x2001), true);
  assert.equal(frameOpaque864c30CapabilityGate(0x1fff), false);
  assert.equal(frameOpaque864c30CapabilityGate(0xffffffff), true);
  assert.equal(frameOpaque864c30CapabilityGate(0xffffdfff), false);

  assert.equal(frameOpaque864c30NeedsHost(0), false);
  assert.equal(frameOpaque864c30NeedsHost(1), true);

  /* Pure early: capability closed → al=0 regardless of lua sample. */
  assert.equal(frameOpaque864c30ResultFromSamples(0, 1), false);
  assert.equal(frameOpaque864c30ResultFromSamples(0, 0), false);
  /* Capability open: al = host_lua_ok (bh post). */
  assert.equal(frameOpaque864c30ResultFromSamples(1, 0), false);
  assert.equal(frameOpaque864c30ResultFromSamples(1, 1), true);
  assert.equal(frameOpaque864c30ResultFromSamples(1, 0xff), true);

  assert.deepEqual(frameOpaque864c30ResidualPlan(0), {
    capability: false,
    pureEarly: true,
    hostBody: false,
    host874910: false,
    host6a80f0: false,
    hostLuaIat: false,
    hostSehLog: false,
    pureCfOk: true,
  });
  assert.deepEqual(frameOpaque864c30ResidualPlan(1), {
    capability: true,
    pureEarly: false,
    hostBody: true,
    host874910: true,
    host6a80f0: true,
    hostLuaIat: true,
    hostSehLog: true,
    pureCfOk: true,
  });
});

test("frame opaque 864c30 SEH vtbl-dispatch peel JS oracle (ABI v18)", () => {
  assert.equal(FRAME_OPAQUE_HOST_693180_VA, 0x00693180);
  assert.equal(FRAME_OPAQUE_864C30_NET_GLOBAL_VA, 0x00c71678);
  assert.equal(FRAME_OPAQUE_864C30_SEH_VTBL_NAME_OFF, 4);
  assert.equal(FRAME_OPAQUE_864C30_SEH_SIDE_RECEIVER_OFF, 0x68d78);
  assert.equal(frameOpaque864c30SehNameVtblSlotOff(), 4);

  /* Unwind never produces a true result: the restored byte is always zero. */
  assert.equal(frameOpaque864c30SehResult(), 0);

  assert.equal(frameOpaque864c30SehSideLogNeeded(0), false);
  assert.equal(frameOpaque864c30SehSideLogNeeded(1), true);
  assert.equal(frameOpaque864c30SehSideLogNeeded(0xffffffff), true);

  /* Receiver bias only forms when the guard passes; 32-bit wrap preserved. */
  assert.equal(frameOpaque864c30SehSideReceiver(0), 0);
  assert.equal(frameOpaque864c30SehSideReceiver(0x1000), 0x1000 + 0x68d78);
  assert.equal(frameOpaque864c30SehSideReceiver(0xfff00000), 0xfff68d78);
  assert.equal(frameOpaque864c30SehSideReceiver(0xffffffff), 0x68d77);

  assert.deepEqual(frameOpaque864c30SehPlan(0), {
    hostNameVcall: true,
    hostAssertLog: true,
    sideLogNeeded: false,
    hostSideVcall: false,
    hostSideLog: false,
    sideReceiver: 0,
    resultAl: 0,
    pureCfOk: true,
  });
  assert.deepEqual(frameOpaque864c30SehPlan(0x20000), {
    hostNameVcall: true,
    hostAssertLog: true,
    sideLogNeeded: true,
    hostSideVcall: true,
    hostSideLog: true,
    sideReceiver: 0x20000 + 0x68d78,
    resultAl: 0,
    pureCfOk: true,
  });

  /* result_from_samples_ex is a superset of the v17 helper. */
  for (const cap of [0, 1]) {
    for (const luaOk of [0, 1]) {
      assert.equal(
        frameOpaque864c30ResultFromSamplesEx(cap, 0, luaOk),
        frameOpaque864c30ResultFromSamples(cap, luaOk),
        `ex superset cap=${cap} lua=${luaOk}`,
      );
      /* An unwind forces false even when the lua sample succeeded. */
      assert.equal(frameOpaque864c30ResultFromSamplesEx(cap, 1, luaOk), false);
    }
  }
});

