    assert.equal(readI32(view, planPtr + 20) !== 0, js.hostNewuserdata, `874910 newud ${row}`);
    assert.equal(readI32(view, planPtr + 24) !== 0, js.host85bff0, `874910 85bff0 ${row}`);
