  assert.match(h, /int32_t isaac_frame_opaque_4212c0_try_pure\(\s*int32_t\* mode,\s*int32_t\* secondary,\s*int32_t field_3c,\s*uint32_t flag_4c,\s*uint32_t slot_char,\s*uint32_t flag_111\);/);
