  /* MULTI-LINE-AWARE 8-bit-parameter census. The census this family
     shipped with v28 was a single-line pattern over `uint8_t` and could
     not see int8_t parameters on their own lines — four survived it and
     all four probed divergent on the shipped module. This parser strips
     comments, joins the whole file, and inspects every parameter of
     every prototype, so a line break can never hide a parameter again. */
  {
    const noComments = h.replace(/\/\*[\s\S]*?\*\//g, " ");
    const params = [];
    const protoRe = /\b(isaac_[A-Za-z0-9_]+)\s*\(([^)]*)\)\s*;/g;
    let m;
    while ((m = protoRe.exec(noComments)) !== null) {
      for (const raw of m[2].split(",")) {
        const arg = raw.trim().replace(/\s+/g, " ");
        if (arg === "" || arg === "void") continue;
        params.push({ fn: m[1], arg });
      }
    }
    /* The census must actually SEE the once-broken prototypes — a
       clean-looking EMPTY result is the known failure mode. */
    const tryPureParams = params.filter((p) => p.fn === "isaac_frame_opaque_4212c0_try_pure");
    assert.equal(tryPureParams.length, 6, "census sees all six try_pure params");
    assert.equal(
      params.filter((p) => p.fn === "isaac_frame_opaque_4212c0_secondary3_after_probe_false").length,
      4, "census sees all four secondary3 params");
    assert.ok(params.length >= 100, `census parsed only ${params.length} params — parser died`);
    const eightBit = params.filter(
      (p) => /^(const )?(u?int8_t|signed char|unsigned char|char)\b/.test(p.arg) && !p.arg.includes("*"),
    );
    assert.deepEqual(eightBit, [], "no by-value 8-bit scalar parameter may remain (multi-line census)");
  }
