  /* The v29 model mirrors the census numbers. */
  assert.equal(FRAME_OPAQUE_9B9480_CALL_SITES, 30);
  assert.equal(FRAME_OPAQUE_9B9310_CALL_SITES, 26);
  assert.equal(FRAME_OPAQUE_417800_CALL_SITES, 9);
