  assert.match(h, /ISAAC_FRAME_OPAQUE_4212C0_TRUE_PROBE_END_VA = 0x004213abu/);
  assert.match(h, /ISAAC_FRAME_OPAQUE_HOST_92E430_VA = 0x0092e430u/);
