/* ---- ABI v37: 0x421620 assign + 0x421680 growth core ---- */

/* Independent PE-truth ref for the growth law: cap = request|0xf then
   clamp 0x7fffffff then min 0x16 (cmovb). request<=0xf -> 0xf inline. */
function a421620GrowRef(request) {
  const r = request >>> 0;
  if (r <= 0x0f) return 0x0f;
  let cap = (r | 0x0f) >>> 0;
  if (cap > 0x7fffffff) cap = 0x7fffffff;
  if (cap < 0x16) cap = 0x16;
  return cap >>> 0;
}

test("frame opaque 421620 string assign + 421680 growth plan (ABI v37)", () => {
  const wa = loadExports();
  assert.equal(FRAME_OPAQUE_PURE_ABI_VERSION, 64);
  assert.equal(FRAME_OPAQUE_421620_VA, 0x00421620);
  assert.equal(FRAME_OPAQUE_421620_END_VA, 0x0042167b);
  assert.equal(FRAME_OPAQUE_421680_VA, 0x00421680);
  assert.equal(FRAME_OPAQUE_421680_END_VA, 0x00421712);
  assert.equal(FRAME_OPAQUE_421680_NEXT_VA, 0x00421720);
  assert.equal(FRAME_OPAQUE_421620_ALLOC_VA, 0x0040cf00);
  assert.equal(FRAME_OPAQUE_421620_MEMCPY_IAT_VA, 0x00af05df);
  assert.equal(FRAME_OPAQUE_421620_THROW_VA, 0x0040ccc0);
  assert.equal(FRAME_OPAQUE_421620_SSO_CAP, 0x10);
  assert.equal(FRAME_OPAQUE_421620_MAX_CAP, 0x7fffffff);
  assert.equal(FRAME_OPAQUE_421620_MIN_GROW, 0x16);
  assert.equal(FRAME_OPAQUE_421620_SRC_LEN_OFF, 0x10);
  assert.equal(FRAME_OPAQUE_421620_SRC_CAP_OFF, 0x14);
  assert.equal(FRAME_OPAQUE_421620_SRC_DATA_OFF, 0x00);

  /* VA + layout exports: wasm / JS oracle lockstep. */
  assert.equal(frameOpaque421620HostVa(), 0x00421620);
  assert.equal(wa.hostVa421620() >>> 0, 0x00421620);
  assert.equal(frameOpaque421620EndVa(), 0x0042167b);
  assert.equal(wa.endVa421620() >>> 0, 0x0042167b);
  assert.equal(frameOpaque421680HostVa(), 0x00421680);
  assert.equal(wa.hostVa421680() >>> 0, 0x00421680);
  assert.equal(frameOpaque421680EndVa(), 0x00421712);
  assert.equal(wa.endVa421680() >>> 0, 0x00421712);
  assert.equal(frameOpaque421680NextVa(), 0x00421720);
  assert.equal(wa.nextVa421680() >>> 0, 0x00421720);
  assert.equal(frameOpaque421620AllocVa(), 0x0040cf00);
  assert.equal(wa.allocVa421620() >>> 0, 0x0040cf00);
  assert.equal(frameOpaque421620MemcpyVa(), 0x00af05df);
  assert.equal(wa.memcpyVa421620() >>> 0, 0x00af05df);
  assert.equal(frameOpaque421620ThrowVa(), 0x0040ccc0);
  assert.equal(wa.throwVa421620() >>> 0, 0x0040ccc0);
  assert.equal(frameOpaque421620SrcLenOff(), 0x10);
  assert.equal(wa.srcLenOff421620() >>> 0, 0x10);
  assert.equal(frameOpaque421620SrcCapOff(), 0x14);
  assert.equal(wa.srcCapOff421620() >>> 0, 0x14);
  assert.equal(frameOpaque421620SrcDataOff(), 0x00);
  assert.equal(wa.srcDataOff421620() >>> 0, 0x00);

  /* max-cap gate: 0x7fffffff - old_cap (u32 wrap) < len -> throw.
     old_cap 0x100 -> room 0x7ffffeff; len 0x7fffff00 <= room (ok),
     len 0x7ffffff0 > room (throw). */
  for (const [len, oldCap, want] of [
    [0, 0, 0], [1, 0, 0], [0x10, 0, 0], [0x7fffffff, 0, 0],
    [0x7ffffffe, 0, 0], [0x100, 0x100, 0], [0x7ffffff0, 0x100, 1],
    [0x40000000, 0x40000000, 1], [0x40000000, 0x3fffffff, 0],
    [-1, 0, 1],
  ]) {
    const js = frameOpaque421620MaxCapExceeded(len, oldCap);
    const waV = wa.maxCapExceeded421620(len, oldCap);
    assert.equal(js, want, `capjs ${len},${oldCap}`);
    assert.equal(waV, want, `capwa ${len},${oldCap}`);
  }

  /* SSO inline: STRICT jb 0x10 — 0x10 IS heap. */
  for (const [cap, want] of [[0,1],[0xf,1],[0x10,0],[0x11,0],[0x100,0]]) {
    assert.equal(frameOpaque421620SsoInlineNeeded(cap), want, `ssojs ${cap}`);
    assert.equal(wa.ssoInlineNeeded421620(cap), want, `ssowa ${cap}`);
  }

  /* growth needed: request > 0xf -> grow. */
  for (const [r, want] of [[0,0],[0xf,0],[0x10,1],[0x11,1],[0x100,1]]) {
    assert.equal(frameOpaque421620GrowthNeeded(r), want, `grjs ${r}`);
    assert.equal(wa.growthNeeded421620(r), want, `grwa ${r}`);
  }

  /* grow cap: ref/wasm/js lockstep incl. wrap and clamp edges. */
  for (const r of [0, 0xf, 0x10, 0x15, 0x16, 0x17, 0x1f, 0x20, 0xff,
                   0x100, 0x7ffffff0, 0x7ffffff1, 0x7fffffff, 0x80000000,
                   0xffffffff]) {
    const js = frameOpaque421620GrowCap(r);
    const waV = wa.growCap421620(r);
    const rf = a421620GrowRef(r);
    assert.equal(js, rf, `grwjs ${r.toString(16)}`);
    assert.equal(waV, rf, `grwwa ${r.toString(16)}`);
    assert.equal(rf, a421620GrowRef(r), `grwref ${r.toString(16)}`);
  }

  /* PE-dead min-grow clause pin: MSVC emits \`mov eax,0x16; cmp
     esi,eax; cmovb esi,eax\` at 0x4216c5, but request|0xf >= 0x1f for
     every request > 0xf (0x10|0xf = 0x1f), so the 0x16 floor never
     fires. Pinned as reproduced-and-documented; not correctable. */
  assert.equal(frameOpaque421620GrowCap(0x10), 0x1f);
  assert.equal(wa.growCap421620(0x10) >>> 0, 0x1f);
  assert.equal(frameOpaque421620GrowCap(0x12), 0x1f);
  assert.equal(frameOpaque421620GrowCap(0x14), 0x1f);
  assert.equal(frameOpaque421620GrowCap(0x15), 0x1f);

  /* 400-draw LCG lockstep js/wasm/ref. */
  {
    let seed = 0x42162037;
    const rnd = () => {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      return seed;
    };
    for (let i = 0; i < 400; i += 1) {
      const a = rnd();
      const b = rnd();
      assert.equal(wa.growCap421620(a) >>> 0, a421620GrowRef(a), `rand grow ${i}`);
      assert.equal(wa.growthNeeded421620(a), frameOpaque421620GrowthNeeded(a), `rand gr ${i}`);
      assert.equal(wa.ssoInlineNeeded421620(a), frameOpaque421620SsoInlineNeeded(a), `rand sso ${i}`);
      assert.equal(wa.maxCapExceeded421620(a, b), frameOpaque421620MaxCapExceeded(a, b), `rand cap ${i}`);
      assert.equal(wa.srcCapOff421620() >>> 0, 0x14, `rand srccap ${i}`);
    }
  }
});



/* ---- ABI v38: 0x421720 bitset membership test (+0x8ac/+0x8bc) ---- */

test("frame opaque 421720 bitset membership test plan (ABI v38)", () => {
  const wa = loadExports();
  assert.equal(FRAME_OPAQUE_PURE_ABI_VERSION, 64);
  assert.equal(FRAME_OPAQUE_421720_VA, 0x00421720);
  assert.equal(FRAME_OPAQUE_421720_END_VA, 0x00421767);
  assert.equal(FRAME_OPAQUE_421720_NEXT_VA, 0x00421770);
  assert.equal(FRAME_OPAQUE_421720_BITMAP_A_OFF, 0x8ac);
  assert.equal(FRAME_OPAQUE_421720_BITMAP_B_OFF, 0x8bc);
  assert.equal(FRAME_OPAQUE_421720_WORD_SHIFT, 5);
  assert.equal(FRAME_OPAQUE_421720_BIT_MASK, 0x1f);

  /* VA + layout exports: wasm / JS oracle lockstep. */
  assert.equal(frameOpaque421720HostVa(), 0x00421720);
  assert.equal(wa.hostVa421720() >>> 0, 0x00421720);
  assert.equal(frameOpaque421720EndVa(), 0x00421767);
  assert.equal(wa.endVa421720() >>> 0, 0x00421767);
  assert.equal(frameOpaque421720NextVa(), 0x00421770);
  assert.equal(wa.nextVa421720() >>> 0, 0x00421770);
  assert.equal(frameOpaque421720BitmapAOff(), 0x8ac);
  assert.equal(wa.bitmapAOff421720() >>> 0, 0x8ac);
  assert.equal(frameOpaque421720BitmapBOff(), 0x8bc);
  assert.equal(wa.bitmapBOff421720() >>> 0, 0x8bc);
  assert.equal(frameOpaque421720WordShift(), 5);
  assert.equal(wa.wordShift421720() >>> 0, 5);
  assert.equal(frameOpaque421720BitMaskConst(), 0x1f);
  assert.equal(wa.bitMaskConst421720() >>> 0, 0x1f);

  /* word index: (id>>5)*4 — id 0..31 -> word 0, id 32 -> word 4. */
  for (const [id, want] of [
    [0, 0], [31, 0], [32, 4], [33, 4], [63, 4], [64, 8], [0x100, 0x20],
    [0xffffffff, 0x1ffffffc],
  ]) {
    const js = frameOpaque421720WordOff(id);
    const waV = wa.wordOff421720(id);
    const rf = ((id >>> 5) << 2) >>> 0;
    assert.equal(js, want, `wordjs ${id}`);
    assert.equal(waV, want, `wordwa ${id}`);
    assert.equal(js, rf, `wordref ${id}`);
  }

  /* bit mask: 1 << (id & 0x1f). */
  for (const [id, want] of [
    [0, 1], [1, 2], [31, 0x80000000], [32, 1], [33, 2], [0xffffffff, 0x80000000],
  ]) {
    const js = frameOpaque421720BitMask(id);
    const waV = wa.bitMask421720(id);
    assert.equal(js, want, `bitjs ${id}`);
    assert.equal(waV >>> 0, want, `bitwa ${id}`);
  }

  /* membership: either word has the bit. */
  for (const [a, b, m, want] of [
    [0, 0, 1, 0], [1, 0, 1, 1], [0, 1, 1, 1], [1, 1, 1, 1],
    [0x100, 0, 0x100, 1], [0x100, 0, 1, 0], [0x101, 0, 0x100, 1],
    [0xffffffff, 0, 0x80000000, 1], [0xffffffff, 0, 0x40000000, 1],
    [0, 0x80000000, 0x80000000, 1], [0xffffffff, 0xffffffff, 0, 0],
  ]) {
    const js = frameOpaque421720Membership(a, b, m);
    const waV = wa.membership421720(a, b, m);
    assert.equal(js, want, `memjs ${a},${b},${m}`);
    assert.equal(waV, want, `memwa ${a},${b},${m}`);
  }

  /* 400-draw LCG lockstep js/wasm/ref. */
  {
    let seed = 0x42172038;
    const rnd = () => {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      return seed;
    };
    for (let i = 0; i < 400; i += 1) {
      const id = rnd();
      const a = rnd();
      const b = rnd();
      const mask = rnd();
      assert.equal(wa.wordOff421720(id) >>> 0, frameOpaque421720WordOff(id), `rand word ${i}`);
      assert.equal(wa.bitMask421720(id) >>> 0, frameOpaque421720BitMask(id), `rand bit ${i}`);
      assert.equal(wa.membership421720(a, b, mask), frameOpaque421720Membership(a, b, mask), `rand mem ${i}`);
      assert.equal(wa.bitmapAOff421720() >>> 0, 0x8ac, `rand aoff ${i}`);
      assert.equal(wa.bitmapBOff421720() >>> 0, 0x8bc, `rand boff ${i}`);
    }
  }
});



