  assert.match(h, /isaac_frame_opaque_424440_copy_snapshot/);
  assert.match(h, /ISAAC_FRAME_OPAQUE_424440_MINUS_ONE_VALUE = 0xffffffffu/);
  /* C++ law bodies pinned: full-dword node relink + zero table + snapshot. */
  assert.match(s, /after-erase relink/);
  assert.match(s, /case 0x1cu: case 0x3cu: case 0x40u:/);
  assert.match(s, /case 0x88u:/);
  assert.match(s, /k == 2u\) \? 1 : 0/);
  assert.match(s, /\+0x18 is the NODE \(not zero\)/);
  /* Host boundary consistent with the exit family's residual: 0x424540
     stays host, 0x424440 laws are a pure prefix. */
