  assert.match(h, /ISAAC_FRAME_OPAQUE_425130_VEC_E_VA = 0x00bab4a0u/);
  assert.match(h, /isaac_frame_opaque_425130_pair_gate/);
  assert.match(h, /isaac_frame_opaque_425130_mode_ge_0x29/);
  assert.match(h, /isaac_frame_opaque_425130_mode_lt_0x15/);
  assert.match(h, /isaac_frame_opaque_425130_lane1/);
  assert.match(h, /isaac_frame_opaque_425130_lane2/);
  assert.match(h, /isaac_frame_opaque_425130_elem_base_off/);
